function clean (value: any): string {
  return String(value ?? '').replace(/\s+/g, ' ').trim()
}

function smartText (value: any): string {
  return clean(value).replace(/'/g, '’')
}

function escXml (value: any): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

function decodeXmlText (value: string): string {
  return String(value || '')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
}

function safeFilePart (value: string): string {
  return clean(value || 'pratica').replace(/[^a-zA-Z0-9_-]+/g, '_').replace(/^_+|_+$/g, '') || 'pratica'
}

function normalizeMoneyLeadingEuro (value: string): string {
  const raw = clean(value)
  if (!raw) return '€ ________'
  const noEuro = raw.replace(/€/g, '').trim()
  return `€ ${noEuro}`.replace(/\s+/g, ' ')
}

function base64ToBytes (b64: string): Uint8Array {
  const g: any = globalThis as any
  const bin = typeof atob === 'function' ? atob(b64) : (g.Buffer ? g.Buffer.from(b64, 'base64').toString('binary') : '')
  if (!bin) throw new Error('Decodifica base64 non disponibile nel browser corrente.')
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

function readU16 (data: Uint8Array, off: number): number {
  return data[off] | (data[off + 1] << 8)
}

function readU32 (data: Uint8Array, off: number): number {
  return (data[off] | (data[off + 1] << 8) | (data[off + 2] << 16) | (data[off + 3] << 24)) >>> 0
}

function u16 (value: number): number[] {
  return [value & 0xff, (value >>> 8) & 0xff]
}

function u32 (value: number): number[] {
  return [value & 0xff, (value >>> 8) & 0xff, (value >>> 16) & 0xff, (value >>> 24) & 0xff]
}

function concatBytes (parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((sum, p) => sum + p.length, 0)
  const out = new Uint8Array(total)
  let off = 0
  parts.forEach(p => { out.set(p, off); off += p.length })
  return out
}

function crc32 (data: Uint8Array): number {
  let crc = 0xffffffff
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i]
    for (let j = 0; j < 8; j++) crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1))
  }
  return (crc ^ 0xffffffff) >>> 0
}

function utf8 (value: string): Uint8Array {
  return new TextEncoder().encode(value)
}

function readUtf8 (data: Uint8Array): string {
  return new TextDecoder('utf-8').decode(data)
}

function readZipStored (data: Uint8Array): ZipEntry[] {
  const entries: ZipEntry[] = []
  const decoder = new TextDecoder('utf-8')
  let off = 0
  while (off + 4 <= data.length) {
    const sig = readU32(data, off)
    if (sig === 0x02014b50 || sig === 0x06054b50) break
    if (sig !== 0x04034b50) break
    const method = readU16(data, off + 8)
    const compressedSize = readU32(data, off + 18)
    const uncompressedSize = readU32(data, off + 22)
    const nameLen = readU16(data, off + 26)
    const extraLen = readU16(data, off + 28)
    const nameStart = off + 30
    const name = decoder.decode(data.slice(nameStart, nameStart + nameLen))
    const dataStart = nameStart + nameLen + extraLen
    const dataEnd = dataStart + compressedSize
    if (method !== 0) throw new Error(`Il template DOCX non è in formato ZIP non compresso: ${name}.`)
    if (compressedSize !== uncompressedSize) throw new Error(`Dimensioni non coerenti nel template DOCX: ${name}.`)
    entries.push({ name, data: data.slice(dataStart, dataEnd) })
    off = dataEnd
  }
  return entries
}

function buildZipStored (entries: ZipEntry[]): Uint8Array {
  const enc = new TextEncoder()
  const locals: Uint8Array[] = []
  const centrals: Uint8Array[] = []
  let offset = 0
  entries.forEach(entry => {
    const name = enc.encode(entry.name)
    const data = entry.data
    const crc = crc32(data)
    const local = new Uint8Array([
      ...u32(0x04034b50), ...u16(20), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(crc), ...u32(data.length), ...u32(data.length), ...u16(name.length), ...u16(0)
    ])
    locals.push(local, name, data)
    const central = new Uint8Array([
      ...u32(0x02014b50), ...u16(20), ...u16(20), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(crc), ...u32(data.length), ...u32(data.length), ...u16(name.length), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(0), ...u32(offset)
    ])
    centrals.push(central, name)
    offset += local.length + name.length + data.length
  })
  const centralStart = offset
  const centralBytes = concatBytes(centrals)
  const end = new Uint8Array([
    ...u32(0x06054b50), ...u16(0), ...u16(0), ...u16(entries.length), ...u16(entries.length), ...u32(centralBytes.length), ...u32(centralStart), ...u16(0)
  ])
  return concatBytes([...locals, centralBytes, end])
}

function parseTextTokens (xml: string): { tokens: TextToken[], fullText: string } {
  const tokens: TextToken[] = []
  const rx = /<w:t(\s[^>]*)?>([\s\S]*?)<\/w:t>/g
  let match: RegExpExecArray | null
  let fullText = ''
  while ((match = rx.exec(xml)) !== null) {
    const openEnd = xml.indexOf('>', match.index) + 1
    const textStart = openEnd
    const textEnd = rx.lastIndex - '</w:t>'.length
    const text = decodeXmlText(match[2] || '')
    const fullStart = fullText.length
    fullText += text
    tokens.push({ start: match.index, end: rx.lastIndex, textStart, textEnd, fullStart, fullEnd: fullText.length, text })
  }
  return { tokens, fullText }
}

function replaceTokenText (xml: string, token: TextToken, text: string): string {
  return xml.slice(0, token.textStart) + escXml(text) + xml.slice(token.textEnd)
}

function replaceTextAcrossRunsOnce (xml: string, needle: string, replacement: string): { xml: string, replaced: boolean } {
  const n = String(needle || '')
  if (!n) return { xml, replaced: false }
  const parsed = parseTextTokens(xml)
  const at = parsed.fullText.indexOf(n)
  if (at < 0) return { xml, replaced: false }
  const end = at + n.length
  const affected = parsed.tokens.filter(t => t.fullEnd > at && t.fullStart < end)
  if (!affected.length) return { xml, replaced: false }
  const first = affected[0]
  const last = affected[affected.length - 1]
  const startInsideFirst = Math.max(0, at - first.fullStart)
  const endInsideLast = Math.max(0, end - last.fullStart)
  const newTexts = new Map<TextToken, string>()
  if (first === last) {
    newTexts.set(first, first.text.slice(0, startInsideFirst) + replacement + first.text.slice(endInsideLast))
  } else {
    newTexts.set(first, first.text.slice(0, startInsideFirst) + replacement)
    for (let i = 1; i < affected.length - 1; i++) newTexts.set(affected[i], '')
    newTexts.set(last, last.text.slice(endInsideLast))
  }
  let out = xml
  ;[...newTexts.entries()].sort((a, b) => b[0].textStart - a[0].textStart).forEach(([token, text]) => {
    out = replaceTokenText(out, token, text)
  })
  return { xml: out, replaced: true }
}

function replaceTextAcrossRuns (xml: string, needle: string, replacement: string): string {
  let out = xml
  for (let guard = 0; guard < 20; guard++) {
    const res = replaceTextAcrossRunsOnce(out, needle, replacement)
    out = res.xml
    if (!res.replaced) break
  }
  return out
}


function getRunBoundsForToken (xml: string, token: TextToken): { runStart: number, runEnd: number } | null {
  let runStart = xml.lastIndexOf('<w:r', token.start)
  while (runStart >= 0) {
    const next = xml.charAt(runStart + '<w:r'.length)
    if (next === '>' || /\s/.test(next)) break
    runStart = xml.lastIndexOf('<w:r', runStart - 1)
  }
  if (runStart < 0) return null
  const runOpenEnd = xml.indexOf('>', runStart)
  if (runOpenEnd < 0 || runOpenEnd > token.start) return null
  const runCloseStart = xml.indexOf('</w:r>', token.end)
  if (runCloseStart < 0) return null
  return { runStart, runEnd: runCloseStart + '</w:r>'.length }
}

function getRunPr (runXml: string): string {
  const match = runXml.match(/<w:rPr>[\s\S]*?<\/w:rPr>/)
  return match ? match[0] : ''
}

function ensureBoldRunPr (runPr: string): string {
  let out = runPr || '<w:rPr></w:rPr>'
  if (!/<w:b\b/.test(out)) out = out.replace('</w:rPr>', '<w:b/></w:rPr>')
  if (!/<w:bCs\b/.test(out)) out = out.replace('</w:rPr>', '<w:bCs/></w:rPr>')
  return out
}

function makeTextRun (text: string, runPr: string): string {
  if (!text) return ''
  const preserve = /^\s|\s$/.test(text) ? ' xml:space="preserve"' : ''
  return `<w:r>${runPr}<w:t${preserve}>${escXml(text)}</w:t></w:r>`
}

function replaceTextAcrossRunsOnceWithBold (xml: string, needle: string, replacement: string): { xml: string, replaced: boolean } {
  const n = String(needle || '')
  if (!n) return { xml, replaced: false }
  const parsed = parseTextTokens(xml)
  const at = parsed.fullText.indexOf(n)
  if (at < 0) return { xml, replaced: false }
  const end = at + n.length
  const affected = parsed.tokens.filter(t => t.fullEnd > at && t.fullStart < end)
  if (affected.length !== 1) return replaceTextAcrossRunsOnce(xml, needle, replacement)
  const token = affected[0]
  const bounds = getRunBoundsForToken(xml, token)
  if (!bounds) return replaceTextAcrossRunsOnce(xml, needle, replacement)
  const startInside = Math.max(0, at - token.fullStart)
  const endInside = Math.max(0, end - token.fullStart)
  const before = token.text.slice(0, startInside)
  const after = token.text.slice(endInside)
  const runXml = xml.slice(bounds.runStart, bounds.runEnd)
  const runPr = getRunPr(runXml)
  const replacementXml = makeTextRun(before, runPr) + makeTextRun(replacement, ensureBoldRunPr(runPr)) + makeTextRun(after, runPr)
  return { xml: xml.slice(0, bounds.runStart) + replacementXml + xml.slice(bounds.runEnd), replaced: true }
}

function replaceTextAcrossRunsWithBold (xml: string, needle: string, replacement: string): string {
  let out = xml
  for (let guard = 0; guard < 20; guard++) {
    const res = replaceTextAcrossRunsOnceWithBold(out, needle, replacement)
    out = res.xml
    if (!res.replaced) break
  }
  return out
}

function patchCoreProps (xml: string, generatedBy: string): string {
  const by = clean(generatedBy) || 'Gestionale Infrazioni Irrigue'
  const now = new Date().toISOString()
  let out = xml
  out = out.replace(/<dc:creator>[\s\S]*?<\/dc:creator>/, `<dc:creator>${escXml(by)}</dc:creator>`)
  out = out.replace(/<cp:lastModifiedBy>[\s\S]*?<\/cp:lastModifiedBy>/, `<cp:lastModifiedBy>${escXml(by)}</cp:lastModifiedBy>`)
  out = out.replace(/<dcterms:modified[^>]*>[\s\S]*?<\/dcterms:modified>/, `<dcterms:modified xsi:type="dcterms:W3CDTF">${now}</dcterms:modified>`)
  return out
}

function buildDocumentXmlFromTemplate (xml: string, m: BozzaDeterminazioneDocxMap): string {
  const nRapporto = clean(m.n_rapporto) || '______'
  const dataRapporto = clean(m.data_rapporto_tecnico) || '________'
  const area = smartText(m.area) || '__________'
  const settore = smartText(m.settore) || '__________'
  const articoloRef = clean(m.articoli_violati_riferimento) || 'dell’art. ____'
  const trasgressore = smartText(m.trasgressore) || '__________'
  const protNum = clean(m.protocollo_fascicolo_numero) || '______'
  const protData = clean(m.protocollo_fascicolo_data) || '________'
  const importo = normalizeMoneyLeadingEuro(clean(m.pagamento_importo_totale))
  const rapportoVisto = `Rapporto tecnico di rilevazione n. ${nRapporto} del ${dataRapporto}, redatto dall’Area ${area} / Settore ${settore}, con il quale sono stati rilevati i fatti riconducibili alla violazione ${articoloRef} delle suddette Norme generali;`
  const rapportoDisp = `del Rapporto tecnico di rilevazione n. ${nRapporto} del ${dataRapporto}, redatto dall’Area ${area} / Settore ${settore}, con il quale sono stati rilevati i fatti riconducibili alla violazione ${articoloRef} delle “Norme generali sulla distribuzione dell’acqua ad uso irriguo”, approvate con Deliberazione del C.d.D. n. 016 del 02.12.2019;`
  const proposta = `Proposta di contestazione relativa al predetto Rapporto tecnico di rilevazione, prot. n. ${protNum} del ${protData}, predisposta dal Settore Catasto, Ruoli e Servizi Territoriali e finalizzata alla contestazione dell’infrazione rilevata e alla quantificazione degli importi dovuti;`
  let out = xml
  out = replaceTextAcrossRuns(out, 'DITTA “__________”', `DITTA “${trasgressore.toUpperCase()}”`)
  out = replaceTextAcrossRuns(out, 'Rapporto tecnico di rilevazione n. ______ del ________, redatto dall’Area __________ / Settore __________, con il quale sono stati rilevati i fatti riconducibili alla violazione dell’art. ____ delle suddette Norme generali;', rapportoVisto)
  out = replaceTextAcrossRuns(out, 'del Rapporto tecnico di rilevazione n. ______ del ________, redatto dall’Area __________ / Settore __________, con il quale sono stati rilevati i fatti riconducibili alla violazione dell’art. ____ delle “Norme generali sulla distribuzione dell’acqua ad uso irriguo”, approvate con Deliberazione del C.d.D. n. 016 del 02.12.2019;', rapportoDisp)
  out = replaceTextAcrossRuns(out, 'Proposta di contestazione relativa al predetto Rapporto tecnico di rilevazione, prot. n. ______ del ________, predisposta dal Settore Catasto, Ruoli e Servizi Territoriali e finalizzata alla contestazione dell’infrazione rilevata e alla quantificazione degli importi dovuti;', proposta)
  out = replaceTextAcrossRunsWithBold(out, '€ ________', importo)
  return out
}

export function getBozzaDeterminazioneDocxFileName (m: BozzaDeterminazioneDocxMap): string {
  const base = safeFilePart(clean(m.n_rapporto) || clean(m.n_rilevazione) || clean(m.objectid) || 'pratica')
  return `bozza_determinazione_${base}.docx`
}

export async function buildBozzaDeterminazioneDocx (m: BozzaDeterminazioneDocxMap): Promise<Uint8Array> {
  const entries = readZipStored(base64ToBytes(TEMPLATE_DOCX_B64))
  const generatedBy = clean(m.generato_da) || 'Gestionale Infrazioni Irrigue'
  const patched = entries.map(entry => {
    if (entry.name === 'word/document.xml') return { name: entry.name, data: utf8(buildDocumentXmlFromTemplate(readUtf8(entry.data), m)) }
    if (entry.name === 'docProps/core.xml') return { name: entry.name, data: utf8(patchCoreProps(readUtf8(entry.data), generatedBy)) }
    return entry
  })
  return buildZipStored(patched)
}
